import * as T from './vendor/three.module.js';
let seed=731;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function canvasMap(draw,size=1024){const c=document.createElement('canvas');c.width=c.height=size;draw(c.getContext('2d'),size);const t=new T.CanvasTexture(c);t.wrapS=t.wrapT=T.RepeatWrapping;t.encoding=T.sRGBEncoding;t.anisotropy=8;return t}
export const stoneMap=canvasMap((c,n)=>{c.fillStyle='#b5b0a0';c.fillRect(0,0,n,n);for(let i=0;i<20000;i++){let a=rand();c.fillStyle=`rgba(${a>.5?'45,49,43':'235,224,199'},${rand()*.12})`;c.fillRect(rand()*n,rand()*n,rand()*4+1,rand()*3+1)}for(let i=0;i<85;i++){let x=rand()*n,y=rand()*n;c.strokeStyle=`rgba(44,48,43,${rand()*.25})`;c.lineWidth=rand()*1.7+.3;c.beginPath();c.moveTo(x,y);for(let j=0;j<5;j++){x+=rand()*50-20;y+=rand()*30-10;c.lineTo(x,y)}c.stroke()} });
export const clothMap=canvasMap((c,n)=>{c.fillStyle='#b7b7ac';c.fillRect(0,0,n,n);for(let i=0;i<n;i+=3){c.strokeStyle=i%2?'#b0b1a5':'#c7c5b5';c.lineWidth=.6;c.beginPath();c.moveTo(i,0);c.lineTo(i,n);c.stroke();c.beginPath();c.moveTo(0,i);c.lineTo(n,i);c.stroke()}for(let i=0;i<180;i++){const x=rand()*n;const gradient=c.createLinearGradient(x,0,x+20,0);gradient.addColorStop(0,'#111a1c00');gradient.addColorStop(.5,'#111a1c22');gradient.addColorStop(1,'#111a1c00');c.fillStyle=gradient;c.fillRect(x,0,20,n)}});
export const woodMap=canvasMap((c,n)=>{c.fillStyle='#999080';c.fillRect(0,0,n,n);for(let i=0;i<900;i++){const y=rand()*n;c.strokeStyle=`rgba(27,27,22,${rand()*.22})`;c.lineWidth=rand()*2;c.beginPath();c.moveTo(0,y);for(let x=0;x<=n;x+=40)c.lineTo(x,y+Math.sin(x*.02+i)*rand()*6);c.stroke()}});
export const strawMap=canvasMap((c,n)=>{c.fillStyle='#c5b28a';c.fillRect(0,0,n,n);for(let i=0;i<n;i+=8){c.strokeStyle='#6a5c4266';c.lineWidth=1.2;c.beginPath();c.moveTo(i,0);c.lineTo(i,n);c.stroke();c.strokeStyle='#eddbafaa';c.beginPath();c.moveTo(0,i);c.lineTo(n,i);c.stroke()}});
export function addDetailedPine(parent,x,z,s=1,lean=.2){const g=new T.Group();g.position.set(x,0,z);g.scale.setScalar(s);parent.add(g);const bark=new T.MeshStandardMaterial({color:0x46443a,map:woodMap,roughness:1,bumpMap:woodMap,bumpScale:.08});function branch(a,b,r){const dir=new T.Vector3().subVectors(b,a);const mesh=new T.Mesh(new T.CylinderGeometry(r*.45,r,dir.length(),9),bark);mesh.position.addVectors(a,b).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),dir.normalize());mesh.castShadow=true;g.add(mesh)}const curve=new T.CatmullRomCurve3([new T.Vector3(0,0,0),new T.Vector3(-.1,1.2,0),new T.Vector3(lean*2,2.4,.1),new T.Vector3(lean*3,3.5,0)]);const trunk=new T.Mesh(new T.TubeGeometry(curve,14,.14,8,false),bark);trunk.castShadow=true;g.add(trunk);
const positions=[],colors=[];const dark=new T.Color(0x172c24),light=new T.Color(0x53604b);function needle(a,b){positions.push(a.x,a.y,a.z,b.x,b.y,b.z);const col=dark.clone().lerp(light,rand()*.7);colors.push(col.r,col.g,col.b,col.r,col.g,col.b)}
for(let k=0;k<7;k++){const h=1.8+k*.22,ang=k*2.399,end=new T.Vector3(lean*h+Math.cos(ang)*(1.6-k*.1),h+.3,Math.sin(ang)*1.1);const start=new T.Vector3(lean*h*.7,h,0);branch(start,end,.065);for(let j=0;j<10;j++){const a=end.clone().add(new T.Vector3((rand()-.5)*1.4,rand()*.18,(rand()-.5)*1));branch(end,a,.018);for(let n=0;n<42;n++){const p=a.clone().add(new T.Vector3((rand()-.5)*.35,(rand()-.5)*.08,(rand()-.5)*.35));const angle=rand()*Math.PI*2;needle(p,p.clone().add(new T.Vector3(Math.cos(angle)*.14,rand()*.14,Math.sin(angle)*.14)));}}}
const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('color',new T.Float32BufferAttribute(colors,3));g.add(new T.LineSegments(geo,new T.LineBasicMaterial({vertexColors:true,transparent:true,opacity:.94})));return g;}
export {createPost} from './render-pipeline.js';
export const rockMap=new T.TextureLoader().load('./assets/ink-limestone.png');rockMap.wrapS=rockMap.wrapT=T.RepeatWrapping;rockMap.repeat.set(1.5,1.5);rockMap.encoding=T.sRGBEncoding;rockMap.anisotropy=8;
export const rockMat=new T.MeshStandardMaterial({color:0xa6a99e,map:rockMap,bumpMap:rockMap,bumpScale:.07,roughness:1});
export function decorateWorld(scene){const lampMat=new T.MeshBasicMaterial({color:0xffb35c});for(const x of [-9,9])for(const z of [-13,3]){const pole=new T.Mesh(new T.CylinderGeometry(.04,.055,2.8,10),new T.MeshStandardMaterial({color:0x39382e}));pole.position.set(x,1.4,z);scene.add(pole);const lamp=new T.Mesh(new T.SphereGeometry(.24,12,8),lampMat);lamp.scale.y=1.3;lamp.position.set(x,2.8,z);scene.add(lamp);const light=new T.PointLight(0xff9d47,.9,5);light.position.copy(lamp.position);scene.add(light);}
const grassMat=new T.MeshStandardMaterial({color:0x4b5945,side:T.DoubleSide,roughness:1});const geo=new T.BufferGeometry(),points=[];for(let i=0;i<500;i++){const x=(rand()>.5?1:-1)*(12+rand()*8),z=-22+rand()*39;for(let k=0;k<4;k++){const h=.15+rand()*.35;points.push(x-.025,0,z,x+.025,0,z,x+(rand()-.5)*.2,h,z+.02)}}geo.setAttribute('position',new T.Float32BufferAttribute(points,3));geo.computeVertexNormals();scene.add(new T.Mesh(geo,grassMat));}
